import { beforLogin } from "@/layout/login";
import app from "@/store/app";
import codeApp from "@code/store/app";
import { Spin } from "@arco-design/web-react";
import { useState, Fragment, useEffect } from "react";
import { BrowserRouter, HashRouter, Router, useHistory, useParams } from "react-router-dom";
import { App } from "@code/App";
import store from "@/store/dev";
import Settings, { settingStore } from "./components/Setting";
import AppSetting from "./components/AppSetting";
import EnvConfig from "./components/EnvConfig";



const Index = beforLogin(() => {
    const params: any = useParams();
    const id = params.id;
    const [isReady, setIsReady] = useState(false);

    useEffect(() => {
        codeApp.tenantId = id;
        app.getAppInfo(id).then(() => {
            store.init().then(async () => {
                setIsReady(true);
            })
        })
    },[])


    return (
        <HashRouter basename={`/preview/${id}`} >
            <EnvConfig />
            {isReady ? (
                <Fragment>
                    <Settings />
                    <App />
                </Fragment>
            ): (
                <Spin loading><div style={{ width: '100vw', height: 200 }}></div></Spin>
            )}
            {/* {isReady? <App />: <Spin loading><div style={{ width: '100vw', height: 200 }}></div></Spin>}
            {isReady? <Settings /> : null } */}
        </HashRouter>
    )
    
})


export default Index;
